local function newSignal()
	local handlers = {}
	local signal = {}
	function signal:Connect(fn)
		table.insert(handlers, fn)
		local conn = {Connected = true}
		function conn:Disconnect()
			self.Connected = false
			for i, f in ipairs(handlers) do
				if f == fn then table.remove(handlers, i) break end
			end
		end
		conn.disconnect = conn.Disconnect
		return conn
	end
	signal.connect = signal.Connect
	function signal:Fire(...)
		for _, fn in ipairs(table.clone(handlers)) do
			task.spawn(fn, ...)
		end
	end
	signal.fire = signal.Fire
	return signal
end

RT.Event = {
	Name = "EVENTDONOTOTUCH",
	OnServerEvent = newSignal(),
	OnClientEvent = newSignal(),
}
function RT.Event:FireServer(...) self.OnServerEvent:Fire(LocalPlayer, ...) end
function RT.Event:FireClient(_, ...) self.OnClientEvent:Fire(...) end
function RT.Event:FireAllClients(...) self.OnClientEvent:Fire(...) end
RT.Event.fireServer = RT.Event.FireServer

RT.Func = {
	Name = "RemoteFunction",
	OnClientInvoke = nil,
	OnServerInvoke = nil,
}
function RT.Func:InvokeClient(_, ...)
	if self.OnClientInvoke then return self.OnClientInvoke(...) end
	return nil
end
function RT.Func:InvokeServer(...)
	if self.OnServerInvoke then return self.OnServerInvoke(LocalPlayer, ...) end
	return nil
end

