local function NS(a)
	local k = {}
	for i = 1, #a, 3 do k[#k + 1] = NumberSequenceKeypoint.new(a[i], a[i + 1], a[i + 2]) end
	if #k < 2 then return NumberSequence.new(a[2] or 0) end
	return NumberSequence.new(k)
end
local function CS(a)
	local k = {}
	for i = 1, #a, 4 do k[#k + 1] = ColorSequenceKeypoint.new(a[i], Color3.new(a[i + 1], a[i + 2], a[i + 3])) end
	if #k < 2 then return ColorSequence.new(Color3.new(a[2] or 1, a[3] or 1, a[4] or 1)) end
	return ColorSequence.new(k)
end
local function R(id) return { __ref = id } end

