local function BuildAssets(container)
	local OBJ, deferred, failed = {}, {}, 0

	for _, g in ipairs(GROUPS) do
		local cls, refs, props = g[1], g[2], g[4]
		for i = 1, #refs do
			local ok, inst = pcall(Instance.new, cls)
			if not ok or not inst then
				inst = Instance.new("Folder")
				failed = failed + 1
			end
			OBJ[refs[i]] = inst
			for k, col in pairs(props) do
				local v = col[i]
				if v ~= nil then
					if type(v) == "table" then
						deferred[#deferred + 1] = { inst, k, v.__ref }
					else
						local good = pcall(function() (inst :: any)[k] = v end)
						if not good then pcall(function() (inst :: any)[k] = nil end) end
					end
				end
			end
		end
	end

	for _, g in ipairs(GROUPS) do
		local refs, parents = g[2], g[3]
		for i = 1, #refs do
			local p = OBJ[parents[i]]
			pcall(function() OBJ[refs[i]].Parent = p or container end)
		end
	end

	for _, d in ipairs(deferred) do
		local target = OBJ[d[3]]
		if target then pcall(function() (d[1] :: any)[d[2]] = target end) end
	end

	for _, mfx in ipairs(MESHDATA) do
		local part = OBJ[mfx[1]]
		if part and part:IsA("BasePart") and mfx[2] ~= "" then
			local sm = Instance.new("SpecialMesh")
			sm.MeshType = Enum.MeshType.FileMesh
			sm.MeshId = mfx[2]
			if mfx[3] ~= "" then sm.TextureId = mfx[3] end
			sm.Scale = mfx[4]
			sm.Parent = part
		end
	end

	for _, inst in ipairs(container:GetDescendants()) do
		if inst:IsA("LuaSourceContainer") then pcall(function() (inst :: any).Disabled = true end) end
	end

	GROUPS, MESHDATA = {}, {}
	return failed
end

Status("montando os assets (7362 instancias)...")
local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()

local CoreProxy = Instance.new("Folder")
CoreProxy.Name = "Server"

local buildOk, buildErr = pcall(BuildAssets, CoreProxy)
if not buildOk then
	Status("falha ao montar os assets: " .. tostring(buildErr), true)
	return
end

if not (CoreProxy:FindFirstChild("Items") and CoreProxy:FindFirstChild("R6") and CoreProxy:FindFirstChild("Inventory")) then
	Status("assets montados incompletos (Items/R6/Inventory ausentes).", true)
	return
end

local keyValue = CoreProxy:FindFirstChild("Key") or Instance.new("StringValue")
keyValue.Name = "Key"
;(keyValue :: any).Value = CONFIG.KEY
keyValue.Parent = CoreProxy

CoreProxy.Parent = character
Status(("assets prontos: %d itens no inventario."):format(#CoreProxy.Items:GetChildren()))

local function Section_Loader()
local players = game:GetService("Players")
local items = CoreProxy:FindFirstChild("Items") or ReplicatedStorage:WaitForChild("Items")
