itemid = 0

lastequiptick = 0

function EquipToolProperly(tool)
	local plr = game.Players[namhere]
	local char = plr.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	lastequiptick = tick()
	local bp = plr:FindFirstChildOfClass("Backpack")
	if hum and bp then
		tool.Parent = bp
		local ok = pcall(function() hum:EquipTool(tool) end)
		if not ok or tool.Parent ~= char then
			tool.Parent = char
		end
	else
		tool.Parent = char
	end
	lastequiptick = tick()
end

function SafeUnequipped(tool, fn)
	tool.Unequipped:Connect(function()
		if tick() - lastequiptick < 0.5 and tool.Parent ~= nil then
			local char = game.Players[namhere].Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if hum then
				task.defer(function()
					if tool.Parent ~= nil and tool.Parent ~= char then
						pcall(function() hum:EquipTool(tool) end)
					end
				end)
				return
			end
		end
		fn()
	end)
end

