local function start_fragmentation_anchor(Position,radius)
	local search = Region3.new(Position-Vector3.new(radius,radius,radius)*1.1,Position+Vector3.new(radius,radius,radius)*1.1)
	repeat
		local finish = false
		iglist = {game.Players[namhere].Character,wepin}
		local parts = workspace:FindPartsInRegion3WithIgnoreList(search,iglist,100)
		for i = 1,#parts do
			if not p:IsA("UnionOperation") then
				table.insert(list,1,parts[i])
			end
		end
		finish = true
	until #parts < 100 and finish

	local t = tick()
	for i = 1,#list do
		local p = list[i]
		if (not p:IsA("UnionOperation")) and  p:IsDescendantOf(fragmentable) and p:GetMass()<3000 and p.Transparency>0.285 and p.Name~='Base' then
			fragmentate(p.CFrame,p.Size,p.BrickColor,Position,radius,p.BackSurface,p.BottomSurface,p.FrontSurface,p.LeftSurface,p.RightSurface,p.TopSurface,p.Transparency,p.Reflectance)
			if #storage < maximumstorage then
				p.FormFactor = "Custom"
				p.Size = stored_partsize
				p.Position = storage_Position
				table.insert(storage,1,p)
			else
				p:Destroy()
			end

		end
		if (not p:IsA("UnionOperation")) and p:IsDescendantOf(fragmentable) and p:GetMass()<53000 and p.Transparency<0.05 and p.Name~='Base' then
			fragmentate(p.CFrame,p.Size,p.BrickColor,Position,radius,p.BackSurface,p.BottomSurface,p.FrontSurface,p.LeftSurface,p.RightSurface,p.TopSurface,p.Transparency,p.Reflectance)
			if #storage < maximumstorage then
				p.Anchored = true
				p.FormFactor = "Custom"
				p.Size = stored_partsize
				p.Position = storage_Position
				table.insert(storage,1,p)
			else
				p:Destroy()
			end

		end
	end
	list = {}

end

