char.Humanoid.Died:connect(function()

	backpackon = true
	if Equipped then
		if char.Humanoid.Health == 0 then
			RAW:Destroy()
			LAW:Destroy()
			fakeheadweld:Destroy()
			fakehead:Destroy()
			if Shooting then
				Shooting = false
			end
			if Aiming then
				Aiming = false
			end
			if Reloading then
				Reloading = false
			end
			Stances = 0
		end

		Equipped = false
	end
end)

function UnEquipped ()
	Equipped = false
	currentequippeditem = 0

	if Shooting then
		Shooting = false
	end
	if Aiming then
		Aiming = false
	end
	if Reloading then
		Reloading = false
	end

	Stances = 0

	pcall(function ()
		AmmoGui:Destroy()
		AmmoGui = OrgAmmoGui:Clone()
		Torso:WaitForChild("Right Shoulder").Part1 = char["Right Arm"]
		Torso:WaitForChild("Left Shoulder").Part1 = char["Left Arm"]

		RAW:Destroy()
		LAW:Destroy()
		fakeheadweld:Destroy()
		fakehead:Destroy()

		char.Torso.Neck.C0 = CFrame.new(0, 1, 0, -1, -0, -0, 0, 0, 1, 0, 1, 0)
		char.Torso.Neck.C1 = CFrame.new(0, -0.5, 0, -1, -0, -0, 0, 0, 1, 0, 1, 0)
	end)
end

function IdleAnim()
	if Equipped then
		tweenJoint(RAW,  nil , GunSettings.RightPos, function(X) return math.sin(math.rad(X)) end, 0.25)
		tweenJoint(LAW,  nil , GunSettings.LeftPos, function(X) return math.sin(math.rad(X)) end, 0.25)
	end
end

function AimAnim()
	if Equipped then

		tweenJoint(RAW,  nil, RAW.C1 *  CFrame.new(-wepin.AimPart.CFrame:toObjectSpace(char.Head.CFrame).p), function(X) return math.sin(math.rad(X)) end, 0.25)
		tweenJoint(LAW,  nil , GunSettings.LeftAimPos, function(X) return math.sin(math.rad(X)) end, 0.25)
	end
end
sprint = false
function SprintAnim()
	sprint = true
	char = game.Players[namhere].Character
	char.Humanoid.WalkSpeed = 30

	spawn(function()
		while sprint do
			if sprint then else break; end
			tweenJoint(RAW,  nil , GunSettings.RightSprintPos, function(X) return math.cos(math.rad(X)) end, 0.25)
			tweenJoint(LAW,  nil , GunSettings.LeftSprintPos, function(X) return math.cos(math.rad(X)) end, 0.25)
			wait()wait()
			if sprint then else break; end
			tweenJoint(RAW,  nil , GunSettings.RightSprintPos2, function(X) return math.cos(math.rad(X)) end, 0.25)
			tweenJoint(LAW,  nil , GunSettings.LeftSprintPos2, function(X) return math.cos(math.rad(X)) end, 0.25)
			wait()wait()
			if sprint then else break; end
			tweenJoint(RAW,  nil , GunSettings.RightSprintPos3, function(X) return math.cos(math.rad(X)) end, 0.25)
			tweenJoint(LAW,  nil , GunSettings.LeftSprintPos3, function(X) return math.cos(math.rad(X)) end, 0.25)
			wait()wait()
		end
		char = game.Players[namhere].Character
		char.Humanoid.WalkSpeed = 16
		sprint = false
		tweenJoint(RAW,  nil , GunSettings.RightPos, function(X) return math.sin(math.rad(X)) end, 0.1)
		tweenJoint(LAW,  nil , GunSettings.LeftPos, function(X) return math.sin(math.rad(X)) end, 0.1)

	end)

end
function NoSprint()
	char = game.Players[namhere].Character
	char.Humanoid.WalkSpeed = 16
	sprint = false
	tweenJoint(RAW,  nil , GunSettings.RightPos, function(X) return math.sin(math.rad(X)) end, 0.1)
	tweenJoint(LAW,  nil , GunSettings.LeftPos, function(X) return math.sin(math.rad(X)) end, 0.1)
end

