local function Section_ChopFire(script)
script.Parent.Touched:connect(function(hit)
	if hit.Parent ~= script.Parent.Parent.Parent then
	if hit.Parent:FindFirstChild("HumanoidRootPart") then
		if not hit.Parent.HumanoidRootPart:FindFirstChild("KidneyStone") then
		script.Parent.Handle.Splat:Clone():Play()
		local kweld = Instance.new("Weld")
		kweld.Name = "KidneyStone"
		kweld.Part0,kweld.Part1 = script.Parent,hit.Parent.HumanoidRootPart
		kweld.C0 = CFrame.new(0,0,0)*CFrame.Angles(math.rad(90),math.rad(0),math.rad(0))
		kweld.Parent = hit.Parent.HumanoidRootPart
		for i,v in pairs (hit.Parent:GetChildren()) do
			if v:IsA("Shirt") or v:IsA("Pants") then v:Destroy() end
			pcall(function() v.Anchored = false end)
			pcall(function() v.Material = "Neon" end)
			pcall(function() v.BrickColor = BrickColor.new("Gold") end)
			pcall(function() v.Mesh:Destroy() end)
			local fire = script.Flame:Clone()
			fire.Parent = v
			game.Debris:AddItem(fire,1)
			if v:IsA("Humanoid") then else game.Debris:AddItem(v,4) end
		end
		wait(0.5)
		spawn(function()kweld.Part0 = nil kweld.Part1 = nil end)
		wait(.1)
		for i,v in pairs (hit.Parent:GetChildren()) do
			pcall(function()
					v:BreakJoints()
					v.BrickColor = BrickColor.new("Smoky Grey")
					v.Material = "Slate"
			end)
		end
		end
	else print("NO ROOT")
	end
	end
end)
end

