local bound = setmetatable({}, {__mode = "k"})

local function runOnce(inst, fn, ...)
	if not inst or bound[inst] then return end
	bound[inst] = true
	if inst:IsA("LuaSourceContainer") then
		pcall(function() inst.Disabled = true end)
	end
	task.spawn(fn, ...)
end

local function bindRig(rig)
	if not rig or bound[rig] then return end
	if not (rig:FindFirstChildOfClass("Humanoid") and rig:FindFirstChild("Torso")) then return end
	bound[rig] = true
	local healthS = rig:FindFirstChild("Health")
	local soundS  = rig:FindFirstChild("Sound")

	local animate = rig:FindFirstChild("Animate")
	if animate then pcall(function() animate.Disabled = false end) end
	runOnce(healthS, Section_Health, healthS or rig)
	if soundS then
		runOnce(soundS, Section_Sound, soundS)
		local ls = soundS:FindFirstChild("LocalSound")
		runOnce(ls, Section_LocalSound, ls or soundS)
	end
end

local CHOP_VARIANTS = {
	Beanknight = Section_ChopBlack,
	Fortknight = Section_ChopWhite,
	Firebean   = Section_ChopFire,
}

local function bindItemScript(inst)
	if not inst:IsA("BaseScript") and not inst:IsA("Script") then return end
	local parent = inst.Parent
	if not parent then return end
	if parent.Name == "CHOPPART" then
		local owner = parent.Parent
		local fn = Section_ChopBlack
		if owner then
			for prefix, variant in pairs(CHOP_VARIANTS) do
				if string.find(owner.Name, prefix, 1, true) then fn = variant break end
			end
		end
		runOnce(inst, fn, inst)
	elseif parent.Name == "Explosive" then
		runOnce(inst, Section_C4, inst)
	end
end

local function scan(root)
	for _, inst in ipairs(root:GetDescendants()) do
		if inst:IsA("Model") then bindRig(inst) end
		if inst:IsA("LuaSourceContainer") then bindItemScript(inst) end
	end
end

workspace.DescendantAdded:Connect(function(inst)
	if inst:IsA("Model") then
		task.defer(bindRig, inst)
	elseif inst:IsA("LuaSourceContainer") then
		task.defer(bindItemScript, inst)
	end
end)
character.DescendantAdded:Connect(function(inst)
	if inst:IsA("LuaSourceContainer") then task.defer(bindItemScript, inst) end
end)

